def find_pleasant_segments(n, m, grid):
    def dfs(x, y, visited):
        stack = [(x, y)]
        while stack:
            cx, cy = stack.pop()
            for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                nx, ny = cx + dx, cy + dy
                if 0 <= nx < n and 0 <= ny < m and (nx, ny) not in visited and l <= grid[nx][ny] <= r:
                    visited.add((nx, ny))
                    stack.append((nx, ny))

    total_segments = 0
    for l in range(1, n * m + 1):
        for r in range(l, n * m + 1):
            visited = set()
            for i in range(n):
                for j in range(m):
                    if l <= grid[i][j] <= r and (i, j) not in visited:
                        dfs(i, j, visited)
                        if len(visited) != r - l + 1:
                            break
                else:
                    continue
                break
            else:
                total_segments += 1

